      "biography": "曾获第34届金曲奖「最佳华语专辑」、第33届金曲奖「最佳作词人」、第12届金音奖「最佳嘻哈歌曲」及第13届金音奖「最佳嘻哈歌曲」、「最佳嘻哈专辑」。2021年于饶舌选秀《大嘻哈时代》担任导师，连手多位嘻哈圈代表打造节目主题曲《凭什么》，2022年举办个人演唱会《PRO MAX》。\n",
