    "2947": {
      "songs": [
        {
          "id": "1990155433",
          "name": "外面有点冷 feat. 蛋堡 Soft Lipa",
          "artists": "国蛋 / 蛋堡"
        },
        {
          "id": "2022405540",
          "name": "White Noise ft. 蛋堡 Soft Lipa",
          "artists": "国蛋 / 蛋堡"
        },
        {
          "id": "1985421725",
          "name": "偷走",
          "artists": "国蛋"
        }
      ],
      "biography": "国蛋，台南人，是蛋堡在台南一中的学弟，毕业于台大化学系。更为人所知的的称号是”Dr.Paper 纸博士”。2007年加入台湾饶舌厂牌颜社后，发行过《Dr. Paper》系列等6张混音碟，〈飞行少女〉、〈Honda & Toyota〉、〈Yesterday〉、〈外面有点冷〉等都是饶舌乐迷们津津乐道的经典歌曲。两张EP《GDN EXPRESS》、《Later That Night》正式上线后，在这个唱片行已经消失的年代，随即空降实时销售排行榜冠军，〈Yesterday〉并以极高的呼声入围第六届金音奖【最佳嘻哈单曲奖】。国蛋坚持地下发行的特殊作法往往造成网友争相购买，作品也因此成为市面上少有的秒杀对象，身为两岸地下饶舌之王，他是网友们热烈讨论的话题歌手，活跃于网络世界。曾远赴纽约求学的他，在美国东岸文化洗礼下，用一口正统饶舌的嘴，征服各界铁粉挑剔的耳。",
      "biographyDate": "2026-11-05"
    },
