    "4479": {
      "songs": [
        {
          "id": "108406",
          "name": "加油！",
          "artists": "林俊杰 / MC HotDog 热狗"
        },
        {
          "id": "2151956989",
          "name": "人上人",
          "artists": "法老 / MC HotDog 热狗"
        },
        {
          "id": "135025",
          "name": "轻熟女 27",
          "artists": "MC HotDog 热狗 / 关彦淳"
        }
      ],
      "biography": "MC HotDog热狗 在华人饶舌萌芽时期，以领航者的角色带给大家太多的惊奇。从小众传播里的「华语地下饶舌第一人」，到掀动华语嘻哈风云的造浪者。\n\nMC HotDog 的音乐标榜着「让人家听的懂的RAP」，因为一路走来他的歌词字字句句都是绝妙经典。以社会第三者的角度看待事物，是他的本领，也是使命，透过歌曲，替大家讲出不敢讲的话；透过歌曲，像槌子重重打到你的心坎。\n\n从出道以来，MC HotDog 踏遍各校园、夜店，并历经与张震岳前往美国 House of Blues 的巡回演出，大量的舞台经验造就 MC HotDog 丰沛的音乐表演实力。2006年由张震岳操刀制作，热狗全创作专辑——挑战饶舌VS摇滚的新音乐作品《Wake up》，其丰富创作风格以黑马之姿勇夺第18届金曲奖最佳国语专辑奖，是 MC HotDog 正式踏上主流市场获得众人高度注目的重要里程碑。\n\n2008年发行《差不多先生》专辑，同名歌曲〈差不多先生〉用更成熟的文字譬喻出自我内心的挣扎和更多的责任，并用更高超的饶舌技巧表达出对于社会的观察和自身生活的经验态度。同年开始和许多知名线上歌手合作歌曲，在音乐上也更有多面的尝试和突破。\n\n2012年发行《贫民百万歌星》，〈贫民百万歌星〉是专辑破题之作。怎样才算富有？怎样才是穷？是街头的平民热狗，还是华丽舞台上的百万巨星？热狗承认自己有肤浅世俗的欲望，有时候会装阔，但内心还是很贫穷，跟每个人一样，要为柴米油盐酱醋茶这些事情担忧。借由这首歌，热狗反映出这个时代的困境：大多数人看似富裕，却鲜少有人能过得起自己想像中的美好生活，对他来说，人宁可活得矛盾，也要坦然面对生活就是很复杂。\n\n另外和老搭档音乐鬼才张震岳默契无间再次合作的歌曲，描述现代人如何困在网络中，表达的能力与沟通的方式逐渐被电脑与社群服务如脸书、PTT控制。热狗的歌词淋漓尽致地批判了现代年轻人被网络拘禁的焦虑，想要离开自己的寂寞与困境，却离不开每天的开机、关机、待机、宕机。而张震岳加入的部分，如同内在心灵的呼喊，在徬徨与困惑中，每个人不过是想为自己的方向找一个解答。《贫民百万歌星》专辑获得第四届金音创作奖最佳嘻哈专辑奖。\n\n2011年每年圣诞节在上海梅赛德斯奔驰文化中心举办万人嘻哈派对至2015年已连续第五年，2012年创下嘻哈歌手登陆香港红墈体育馆演唱会开唱纪录。2013年第一位华人饶舌歌手在台北小巨蛋举办万人HIP-HOP派对，2015年和 张震岳＆顽童MJ116 组成兄弟本色，开始日落黑趴世界巡回演出并在歌曲创作上碰撞出更多的火花。\n\n2019年，睽违七年发行专辑《废物》，并开始「废欲清巡回演唱会」。\n\n2022年发行专辑《姚中二》，入围第34届金曲奖最佳华语男歌手奖及最佳最词人奖。\n\n2023年发行最新专辑《脏艺术家》依旧执着言词的利刃，但 MC HotDog热狗 这次剖开自己的心，掏出内在的柔软与赤诚，袒露众生皆有的迷惘与脆弱。收录在专辑最后的同名歌曲〈脏艺术家〉大开大阖的傲骨护着逐梦初心，MC HotDog热狗 深刻了解每个人都是自己生命的战斗者，横眉冷对千夫指也要忠于自我地活着。这首歌在2022年第一次做现场发表时，在场的 Rapper 无不动容落泪，风风雨雨二十多年淬炼出的坚定意志与包容是 MC HotDog热狗 来自街头最坚实的拥抱。",
      "biographyDate": "2026-11-05"
    },
