      "biography": "宋岳庭（1978年11月6日－2002年8月9日），英文名Shawn，网络代号M80，为台湾知名饶舌作词作曲家，癌症病逝，年仅二十三岁。被誉为“社会底层发言人”，用歌词道出了社会的黑暗和悲哀。逝世后，得到了第十五届金曲奖。",
