    "12059049": {
      "songs": [
        {
          "id": "1462875618",
          "name": "不怪她",
          "artists": "HARIKIRI / Bohan 冷博涵 / 马思唯 / J.Mag"
        },
        {
          "id": "1462875616",
          "name": "一无所有",
          "artists": "HARIKIRI / Bohan 冷博涵 / 马思唯 / J.Mag"
        },
        {
          "id": "1449822900",
          "name": "刘玉玲 Lucy Liu (feat. Bohan Phoenix)",
          "artists": "PSY.P / Higher Brothers / Bohan 冷博涵"
        }
      ],
      "biography": "Bohan 11岁从湖北移民到美国波士顿。他爱上了嘻哈音乐，并通过模仿着Eminem以及Lauryn Hill的说唱很快学会了说英语。今天，Bohan是中美音乐界里的一种特别的存在；在中英双语和东西文化中间游刃有余的他，用歌曲在两个家乡的鸿沟中诉说着华人的故事。 Bohan以作品中的真诚为自豪，他的音乐讲述着自己的故事却又和每个人息息相关。从他的生活和他周围的世界中汲取灵感，Bohan歌曲里的真实感赢得了全球粉丝和同行的喜爱和尊重。MC Jin欧阳靖，Higher Brothers 海尔兄弟只是他众多合作者中的两个。\n\n2022年，Bohan打破了更多界限：他成为第一位不仅在一次而是三场NBA半场表演的中国说唱歌手，也是第一位在著名的Pirelli日历和 Vogue上拍摄的亚洲男模特，与Cher、Iggy Pop和Grimes 等巨星一起。 Bohan的独立精神为他赢得了轩尼诗、Beats by Dre和Vans品牌大使的角色。同时也可以在迪士尼和Netflix电影的原声带中听到他的歌曲，以及热爱的篮球游戏NBA2K。bohan计划在2023年发出很多的新音乐，他将继续打破期待。\n\n工作邮箱：business@rolldice.cn",
      "biographyDate": "2026-11-05"
    },
