    "12065096": {
      "songs": [
        {
          "id": "523251474",
          "name": "说散就散",
          "artists": "艾福杰尼 / 黄旭BooM / 田羽生"
        },
        {
          "id": "2705348454",
          "name": "出发的理由",
          "artists": "黄旭BooM / Top Barry"
        },
        {
          "id": "1844152730",
          "name": "少数派报告",
          "artists": "TizzyT / VaVa毛衍七 / Jony J / 布瑞吉Bridge / 黄旭BooM"
        }
      ],
      "biography": "黄旭（BooM），1990年8月4日出生于新疆阿克苏，说唱歌手、音乐制作人。\n\n黄旭，知名说唱歌手-唱作人，以强有力的西北说唱技术流著称。代表作品:《天堂来信》 《比个v》《半山腰的风景》。故事性可能是黄旭RAP创作中最明显的一个元素，借助rap表达他的思想态度。13年开始接触说唱，从地下battIe比赛冠军一 路走到《中国新说唱》总决赛。黄旭在各类音乐节以及巡演中，凭借如鱼得水的舞台表演经验，强大的控场能力和观众的互动将现场气氛带到高潮。他在用自己的方式传承oIdschooI精神以及输出他对文化的理解，多样性的音乐更给予了他“说唱教官”的titIe。\n曾参与2017《中国有嘻哈》年度6强；2019年正式签约摩登天空，加入hiphop厂牌MDSK；同年参与《中国新说唱》，进入潘玮柏战队，获得年度亚军。2023年《中国说唱巅峰对决》冠军联盟发起人。",
      "biographyDate": "2026-11-05"
    },
