    "12111238": {
      "songs": [
        {
          "id": "2050062773",
          "name": "带刺儿的玫瑰",
          "artists": "鱼头_killa4nia / 儿几 / 滇声气 / 花生 / Round_2 / step.jad依加"
        },
        {
          "id": "1862570582",
          "name": "2021 MDSK CYPHER",
          "artists": "黄旭BooM / 李大奔BENZO / 满舒克 / OB03 / STARR J / TizzyT / KAFE.HU胡懿 / 儿几 / Saber梁维嘉 / GBZ"
        },
        {
          "id": "538876056",
          "name": "李白",
          "artists": "儿几"
        }
      ],
      "biography": "摩登天空旗下艺人儿几生于光明路 字 月大电月赞 AKA 腌臜. 与拾陆共同拟划“自冄.” 于17年加入厂牌天山摇摆客*********. 一直只存在于underground的rapper儿几, 终于在16年里浮出于水面，歌曲作品首次入住网易云, 这位比隐藏还隐藏的角色在14年里, 悄悄发行了他第一张EP《儿几的》,时隔两年, 在16年又发行了第二张EP《光明路》专辑同名歌曲光明路并取得中国嘻哈榜第6名的成绩.\n2017年11月《9/13 》EP中的歌曲<儿几的FREESTYLE>在上榜两星期后登入中国嘻哈榜榜首为当期冠军。\n2018年新年夜发布单曲《李白》再一次证明了儿几的实力和恐怖的创作力。\n这位94年的年轻人带着他新鲜的flow和熟透的韵会带你尝到你忘不掉的甜头,在trap迷乱的年代选歌慎重“”陷阱“”太多 也许儿几才能带给你纯天然的感觉就像他纯天然的存在着。《儿几的》与《光明路》均为JarFar MIX（shout out to 团结路). 个别分级未发布作品 提供在虾米试听下载. 谢谢你的支持和品位 自冄燃自自然 ********* Peace. 微博：儿几天山摇摆客*********\n虾米：儿几",
      "biographyDate": "2026-11-05"
    },
