    "12195296": {
      "songs": [
        {
          "id": "1908487538",
          "name": "克什米尔山羊",
          "artists": "Capper / YOUNG13DBABY / kattie凯欣 / SanJin"
        },
        {
          "id": "1499989691",
          "name": "Best Friend 好朋友",
          "artists": "Chopie / YOUNG13DBABY"
        },
        {
          "id": "1970396864",
          "name": "圣安地列斯",
          "artists": "KKECHO / YOUNG13DBABY / REDBOI"
        }
      ],
      "biography": "YOUNG13DBABY自16岁起，怀揣着冲出雪山 、席卷全球的音乐梦想，离开玛曲草原来到成都展开了自己的音乐生涯。这位年轻的音乐人将天生不羁的性格与民族特色，结合神秘的雪怪文化，制造出了他独有的“雪怪音乐”氛围。从出道至今已发布超百首音乐作品，不论是在嘻哈世界亦是主流舞台，都能看到他的身影。\n\n2019年，凭借由Empire唱片发行的个人首张录音室专辑《喜玛拉雅的雪》，一举成名。其中“Shanghai”,“Himalaya Drip(feat.Gunna)”,“1234”等数首热门单曲相继火爆各大社交媒体，斩获全球流媒体总播放量超3亿次。并在同年成功受邀登上了美国SXSW音乐节的舞台，紧接着收到全球著名百大DJ KSHMR进行合作邀约，一同推出舞曲“Best Life”。在2020年，刚刚展露头脚的他并没有停下自己的脚步！持续输出热门单曲“Dumb”，“Dior(feat.马思唯/Knowknow）”……同时他也受到了来自国内主流明星的青睐，与黄子韬、马伯骞共同推出合作单曲“Way Too Fast”，获得业界一致好评……\n在2021年，作为AFGK Records成员，参与《Goodkidstape 1》。随后与Capper合作推出爆红单曲“克什米尔山羊”。同年发布第二张个人录音室专辑《玛曲陷阱明星》，精良的音视制作水平将其艺人形象再次提升。2023年携手丁真珍珠，以全球先锋音乐（Melody Drill/Jersey Club）的视角，再次将草原经典歌曲《玛由姑娘》进行传唱。同年登上全球最大嘻哈音乐节Rolling Loud Thailand主舞台，与全球众多顶尖说唱明星同台演绎！2024年，受邀出席《时尚芭莎》年度派对，与韩红老师演唱合作曲目“DXGMD”。",
      "biographyDate": "2026-11-05"
    },
