    "12206205": {
      "songs": [
        {
          "id": "1299550338",
          "name": "殉情",
          "artists": "夏之禹"
        },
        {
          "id": "1479199266",
          "name": "We We (Live)",
          "artists": "刘悦spam-生番 / Lcz小强 / step.jad依加 / 夏之禹 / 鱼翅Fin / 迪木 / 汽油"
        },
        {
          "id": "2046244146",
          "name": "姐姐",
          "artists": "夏之禹"
        }
      ],
      "biography": "夏之禹，说唱浪漫派，2020年「说唱新世代」人气选手。\n凭借充满浪漫的想象⼒与诗意的情绪表达的夏之禹备受乐迷与专业媒体好评。\n2020年参加了B站自制说唱节目「说唱新世代」，凭借极具人文气息与真性情的舞台呈现使他成为了节目人气选手。节目中单曲「we we」「Hometown」 「We Can Be Chillin」成为热门单曲。\n与此同时，个人单曲「殉情」MV在B站播放量突破100万，让大家认识到夏之禹的浪漫魅力。\n于2020年底发行的Mixtape「Young Fresh Chin」，对严肃的时代议题以浪漫化的表达，并呈现出极强对画面感，被多家专业媒体选为年度最佳专辑，更被媒体称做“说唱贾樟柯”。",
      "biographyDate": "2026-11-05"
    },
    "12206277": {
      "songs": [
        {
          "id": "3449060003",
          "name": "老枪",
          "artists": "丹镇北京 / 管管 Guan / 张千C.Jam / Saber梁维嘉 / 刘悦spam-生番 / 中俄艾迪AIDI RUSCHINO / 黄硕N-Bomb / Stinging Ray / DJ Quaver"
        },
        {
          "id": "2010301694",
          "name": "Cypher",
          "artists": "丹镇北京 / DJ Quaver / 刘悦spam-生番 / 黄硕N-Bomb / 张千C.Jam / Stinging Ray / Saber梁维嘉 / Mido美朵 / 中俄艾迪AIDI RUSCHINO / 斯威特MCSWEET"
        },
        {
          "id": "2010301677",
          "name": "地牢中",
          "artists": "丹镇北京 / DJ Quaver / 黄硕N-Bomb / Stinging Ray / General Huge"
        }
      ],
      "biography": "DJ Quaver\n丹镇北京旗下dj，爽子乐队DJ，Natural Flavor指定DJ\nMPC手指鼓演奏者，音乐制作人，beats maker。\n \n2012年底加入“刺儿乐队”担任采样、dj。\n2013年底乐队发表第一张ep，得到业内一致好评，\n同年随队以开场嘉宾身份参加了扭曲机器、\ncmcb等多支国内知名说唱金属乐队的演出。\n \n2014年加入黄硕“铁拳乐队”担任采样、dj。\n期间进行了多次大型演出活动。\n \n同年，开始与丹镇旗下说唱歌手梁维嘉saber合作发表专辑，\n并开始以dj身份活跃于北京各大说唱演出活动以及\n受邀在各种品牌商业活动进行表演。\n  \n2016年，作为初始成员加入丹镇北京厂牌，\n担任厂牌演出dj并负责厂牌旗下艺人的伴奏制作及后期制作工作。\n\n2019年，加入爽子乐队，担任乐队采样、DJ。\n\n2021年，与爽子合作发行西海岸风格说唱专辑《上岸》",
      "biographyDate": "2026-11-05"
    },
