      "biography": "张千C.Jam(Chillin' Jam)\n微博&小红书:张千C-Jam\n抖音:C.Jam\n2012年Iron Mic北京赛区冠军 全国总决赛四强\n演员/独立音乐人\n从2008年8月开始便活跃于各种Freestyle Battle比赛,并于2012年获得Iron Mic北京赛区冠军,全国四强.2016年与好友建立丹镇北京独立音乐厂牌.2018年被End Of the Weak授权以主理人身份运营E.O.W China,并将End Of the Weak译名为强食弱肉.2025年成立Boogie Town Music.",
