      "biography": "王嗣尧TURBO，GOSH MUSIC, 永力兄弟会和 20XX CLUB厂牌成员。全方位的创作型实力音乐人，气质优雅且真诚。在创作中对于自己的音乐风格有着精准的定位，擅长以娓娓道来的形式描述个人的所见所想，略为慵懒的歌曲旋律中常常富含着深刻的哲思。",
