    "12605500": {
      "songs": [
        {
          "id": "1964676839",
          "name": "隆里电丝",
          "artists": "盛宇D-SHINE"
        },
        {
          "id": "2054298885",
          "name": "诀爱·尽 (LIVE版)",
          "artists": "盛宇D-SHINE / Faye 詹雯婷"
        },
        {
          "id": "2694367060",
          "name": "从前以后PT.1",
          "artists": "盛宇D-SHINE / KEY.L刘聪"
        }
      ],
      "biography": "盛宇（D-SHINE）中国著名说唱组合C-BLOCK队长、中国最具影响力的说唱厂牌SUP MUSIC创始人、华语音乐人、演员、词曲创作者、MV导演、制作人。中国规模最大的HIP-HOP音乐节“YOLO青年文化节”创始人、中国头部服装潮牌“BIPOLAR”主理人、街头篮球俱乐部“FlyBoy胡来波”创始人兼球员、 “IELO”CLUB老板\n\n2018年纪录片《从无到有》，记录盛宇和美国说唱同行的交流与演出\n2019年和陌陌、VICE联合推出4集公路音乐纪录片《陌路同途》，记录C-BLOCK\n新歌《很高兴认识你》创作过程获得2019“金瞳奖”“最佳原创内容栏目纪录片+最佳系列微电影”银奖 2018年创作单曲《长河》并入围网易云音乐热歌榜\n2019年为公安部人民检察网“劝止酒驾”公益活动创作公益歌曲《醉酒的满哥》\n2019年获得融合嘻哈颁奖典礼·最受欢迎说唱团体\n2019年为爱奇艺极速版创作广告单曲《越快越AI》并拍摄MV\n2019年为斗牛APP创作广告单曲《牛得拿来斗》并拍摄MV\n2020年参加“网易云点亮现场行动”线上音乐会，数据夺冠，票房&弹幕有效观看均创新高\n2020年为伊利经典创作广告单曲《Let it go》并拍摄MV\n2020年为腾讯游戏《NBA2Kol2》创作广告弹幕《野草蛮生》并拍摄MV\n2021年参与拍摄湖南卫视纪录片《傲椒的湘菜》\n2021获得“硬地围炉夜”网易云音乐原创盛典·年度乐队/团体奖\n2021年担任QQ音乐“地下八英里”全国总决赛评委\n2021年为20集电视连续剧《我是真的爱你》创作插曲《Respect》，该剧由北京卫视、东方为主播出\n2021年受联合国艾滋病规划署、中国预防性病艾滋病基金会、淡蓝公益委托创作公益歌曲《孤影》并拍摄MV\n2019 《中国新说唱》选手，获得季军 2020 《中国新说唱》担任嘉宾大魔王 2020 晚会《元宵一家亲》，创作并演唱抗疫歌曲《屋檐》\n2020 参加CCTV 综艺频道《我要上春晚》获得直通春晚资格 2021 直播晚会《抖音 新潮好物夜》\n2021 《天天向上》，创作并演唱开场曲《CSC love》\n2021 《少年说唱企划》担任导师 2021 《拳力以赴的我们》最佳人气热门拳手",
      "biographyDate": "2026-11-05"
    },
