    "27726025": {
      "songs": [
        {
          "id": "31168104",
          "name": "夜三里",
          "artists": "龙井说唱 孙旭"
        },
        {
          "id": "33941997",
          "name": "兄弟",
          "artists": "龙井说唱 孙旭"
        },
        {
          "id": "36586719",
          "name": "高级动物",
          "artists": "陈伟伦 / 郝云 / 马頔 / 邵夷贝 / 王韵壹 / 郁可唯 / 果味VC / 龙井说唱 孙旭 / 扭曲机器 / 脑浊乐队 / 好妹妹乐队 / 莫西子诗"
        }
      ],
      "biography": "龙井说唱的创始人、成员。精通街球，街舞，说唱，涂鸦，服饰等所有街头文化，是公认的师傅级人物。2003年前后曾组建街球队cotic，是一位街头花式篮球球手。2007年组建龙井说唱团体后成为一位说唱歌手，是一位在说唱界有着重量级身份的人物。\n孙旭独树一帜的京韵、京腔，使其创作了一系列脍炙人口的中文说唱。尤其《孙大圣》一曲很好的诠释了自己本身。他充满中国风的韵味得到了大家的认可和支持。不断的创新和坚持也让他陆续推出了新的作品。《及时行乐》《回到未来》《请多关照》等一些列备受好评的作品，网络播放量均超过百万。2017年推出了优秀作品《修炼》。已成为中国说唱的标志性人物之一。2018年7月，参加爱奇艺综艺节目《中国新说唱》，晋级全国23强。",
      "biographyDate": "2026-11-05"
    },
    "27866110": {
      "songs": [
        {
          "id": "3436810753",
          "name": "其实我们谁都不是医生",
          "artists": "张方钊 / Louis 1520"
        },
        {
          "id": "1965929258",
          "name": "反派英雄",
          "artists": "张方钊 / Louis 1520"
        },
        {
          "id": "1390255360",
          "name": "deadstar(FEAT.1520)",
          "artists": "MISTERK / Louis 1520 / 网上邻居official"
        }
      ],
      "biography": "louis1520，本名刘志德，中国大陆先锋音乐人，来自网上邻居/Wastedclub音乐厂牌，常年活跃于pluggnb、emo等地下音乐场景，在其2023年发布团队专辑《大牌走在东里路》后，靠其独特的音色和flow在圈内独树一帜。曾登上Tuz with hiphop电台表演，在刚接触音乐第一年便与美、日、韩三国歌手共同制作单曲，作为嘉宾参与网上邻居、wastedclub、medm、nous、trapcn等全国巡回演出超过五十场，并多次登上ayo放学嗨、草莓音乐节等大型舞台。在全球范围流媒体平台音乐播放量超过一亿次，音乐视频播放量超过一千万，代表作《西太后》《Hbk2024》《God Bless》等。",
      "biographyDate": "2026-11-05"
    },
    "27868624": {
      "songs": [
        {
          "id": "482056804",
          "name": "高，还没富，但帅",
          "artists": "Ty. / PSY.P / KnowKnow"
        },
        {
          "id": "1457248123",
          "name": "R&B All Night (Masiwei Remix)",
          "artists": "马思唯 / KnowKnow"
        },
        {
          "id": "3455152541",
          "name": "你的故乡是月球",
          "artists": "法老 / KnowKnow"
        }
      ],
      "biography": "被纽约时报赞誉为“中国Hip-Hop界突破性明星说唱组合 - Higher Brothers“ 的唱将担当，KnowKnow早已是一个耳熟能详的名字。这位96年出生的天才旋律制造者出道至今已发布一张个人Mixtape《MEDM》和一张个人正式专辑《Mr. Enjoy Da Money》， 并凭借“R&B All Night”，“Lover Boy 88“， “Midsummer Madness” “Made in China” 等数首单曲屡次在全球范围掀起狂潮，全球试听量超过4.5亿。从2017年与团队Higher Brothers发布首张正式专辑《Black Cab》开始，国内外巡演“座无虚席”；到2018年8月KnowKnow和组合中其他三人共同登上了福布斯中国“30岁以下精英榜”；再到2019年团队第二张正式专辑《Five Stars》中与优秀Hip-hop音乐人们的合作包括Schoolboy Q，Denzel Curry，Soulja Boy，J.I.D等；2019年与Snoop Dogg合作发布单曲“Friends and Foes”，成为首个与欧美rapper共同为美剧打造主题曲的中国rapper。其团队大热单曲《恭喜发财》在抖音更是有超过40万视频使用，全球总播放量超过40亿。2018年KnowKnow与同厂牌88rising旗下艺人Joji，Rich Brian 和 August 08合作88rising厂牌夏日合辑主打歌《Midsummer Madness》，并凭借这首单曲成为中国唯一获得RIAA认证金唱片的说唱歌手，歌曲更是登顶Spotify “全球热门50“榜单。他的2019年年度浪漫金曲“R&B All Night” 在全网掀起翻唱热潮，在抖音互动人数破20万次，单曲播放量超过2亿，包揽各大流媒体榜单第一名。首张个人专辑《Mr. Enjoy Da Money》不仅包含了代表中国顶尖Hip-Hop水平的佳作，更有无法取代的Know式金曲，体现了KnowKnow说唱俱佳的多面天赋，专辑中还有马思唯贡献的两首强力feature，以及中国流行音乐唱作人王嘉尔的倾力加盟。2020年KnowKnow首次以导师身份与黄子韬，Rich Brian，马思唯，李宇春，MC Hotdog同台加入bilibili首档S+级综艺《说唱新世代》，成为2020音乐综艺中一匹黑马，创下单集播放量过亿的惊人成绩。毋庸置疑的是，KnowKnow正用他独有的音乐风格，具有感染力的歌词，和无限的创造力，引领着新一代中国说唱界风潮。",
      "biographyDate": "2026-11-05"
    },
