    "36399677": {
      "songs": [
        {
          "id": "2684175776",
          "name": "老大",
          "artists": "61H / azazel"
        },
        {
          "id": "2709977035",
          "name": "我们要找个地方坐着聊天",
          "artists": "61H"
        },
        {
          "id": "2684177624",
          "name": "软中华硬玉溪",
          "artists": "61H / azazel"
        }
      ],
      "biography": "61H，2004年出生于山东烟台。61H习惯将带有“黑色幽默”的歌词与具有迷幻色彩的伴奏相结合，也善于使用各种熟悉却又意想不到的采样。\n\n14岁时，61H受到SoundCloud上互联网音乐人的影响，开始自行制作伴奏并独立发布音乐。2018年至2020年间，他曾以“lil driver”“Playboi Henry”等艺名发布地下说唱专辑与单曲，曾受到美国主流说唱歌手24kGlodn关注。\n\n2022年，61H正式以“61H”为艺名展开音乐活动，并发布首张正式公开专辑《Explor3》。专辑中的《一二三》曾获得Bloodzboi、Organ Tapes等国内外艺术家的转发与认可。同年，61H参与上海地下音乐厂牌Genome6.66Mbp及摩登天空旗下厂牌Digi相关演出。\n\n2023年，61H先后发布个人独立EP《天窗》与专辑《戒断期》，随后暂别音乐活动并前往韩国留学。在韩国期间，他受到当地地下音乐文化的影响并安心打磨学习音乐制作，并于2025年正式回归。\n\n2025年初，61H与国内音乐制作人azazel先后发布《音秽岛》与《红蓝星》两张EP，其中《上海梦》《软中华硬玉溪》《老大》等作品在互联网平台获得广泛传播。《老大》全球流媒体平台累计播放量突破1000万。同年6月，61H发布个人mixtape《二十》，获得广泛关注。\n\n2025年年中，61H与北京音乐厂牌Table展开个人首次全国巡演，巡演覆盖北京、上海、广州三站，其中广州站门票于演出当晚售罄。2025年年末，61H以Genome6.66Mbp旗下艺人身份发布专辑《败家子》，其中《这小伙》MV在互联网平台获得超过百万次浏览，其采样亦曾引发相关讨论。\n\n2026年初，61H入选国际时尚杂志Dazed评选的“2026年潜力音乐人”名单。同年，他先后登陆中国香港HKCR、韩国Seoul Community Radio进行Live Set，并于日本东京地下俱乐部Circus进行演出。",
      "biographyDate": "2026-11-05"
    },
    "36455161": {
      "songs": [
        {
          "id": "3449060003",
          "name": "老枪",
          "artists": "丹镇北京 / 管管 Guan / 张千C.Jam / Saber梁维嘉 / 刘悦spam-生番 / 中俄艾迪AIDI RUSCHINO / 黄硕N-Bomb / Stinging Ray / DJ Quaver"
        },
        {
          "id": "2010301694",
          "name": "Cypher",
          "artists": "丹镇北京 / DJ Quaver / 刘悦spam-生番 / 黄硕N-Bomb / 张千C.Jam / Stinging Ray / Saber梁维嘉 / Mido美朵 / 中俄艾迪AIDI RUSCHINO / 斯威特MCSWEET"
        },
        {
          "id": "3334605071",
          "name": "北方的夜",
          "artists": "丹镇北京 / 刘悦spam-生番 / Stinging Ray / 黄硕N-Bomb / 中俄艾迪AIDI RUSCHINO / Saber梁维嘉 / 张千C.Jam"
        }
      ],
      "biography": "刘锐(Stinging Ray)是从Hip-Hop派对中走出来的音乐人，也是说唱厂牌\"丹镇北京\"的创始成员，同时还是一名狂热的Reggae音乐人和DJ，他与法国制作人General Huge开办了中国第一家以雷鬼音乐风格为主的唱片公司和发行公司\"ChinaMan Yard Records\"，并负责着牙买加驻华使馆每年的\"Bob Marley Day\"。\n\n在2023年6月16日，刘锐发行了他的第一张个人专辑《Fantasy & Waitin' To Cross Caribbean》(加勒比海的幻想与等待)，在制作团队名单中你会看到像Roots Radics Band、Sly Dunbar和Dean Fraser等等牙买加传奇雷鬼乐队与老中青三代艺术家的助阵与合作，在张专辑中他与成都本土雷鬼乐队Jah Wah Zoo合作的单曲《No Remedy》被全球第一的雷鬼音乐公司VP Records推送到了2022年的\"International Reggae Day\" (世界雷鬼日)。他与法国著名的雷鬼唱片公司iRiE iTES合作的单曲《Fire In Your Eyes》被英国BBC Radio 1Xtra收录到当月电台。新专辑一经发布Stinging Ray就成为了日本雷鬼网站\"Reggae Zion\"的当月封面人物，在为期三个月的新专辑欧洲巡演中，他的专辑和单曲广受好评，他的\"Dubplate\"也随着DJ们在欧洲各地举办的雷鬼派对上播放，巡演期间刘锐也正式成为了iRiE iTES的海外艺人，他的名字也在2023年夏天登上了全球最大的雷鬼音乐杂志\"RIDDIM\"的九月刊专访……",
      "biographyDate": "2026-11-05"
    },
