    "47192128": {
      "songs": [
        {
          "id": "1974459985",
          "name": "麒麟",
          "artists": "早安"
        },
        {
          "id": "1340535891",
          "name": "Kill The Game",
          "artists": "Round_2 / 贰万 / 早安"
        },
        {
          "id": "1969923877",
          "name": "麒麟 (LIVE版)",
          "artists": "早安"
        }
      ],
      "biography": "早安，中国内地华语说唱男歌手、演员，种梦音乐D.M.G旗下签约艺人，说唱双冠军。2021年《说唱听我的》总冠军；2022年《中国说唱巅峰对决》冠军联盟成员；QQ音乐融合嘻哈颁奖礼中获“年度新晋艺人”。代表作：《麒麟》、《Pillow》、《收声》、《Kill The Game》、《翻身仗》等\n\n2021年拿下芒果TV《说唱听我的》第二季总冠军。节目中他与中国新艺术音乐歌唱家龚琳娜，联袂双子星组合尝试了多个颠覆大众印象的说唱舞台。演绎了融合国风艺术与潮流说唱的神级舞台《不忐忑》，并获得QQ音乐融合嘻哈颁奖礼 “最佳综艺说唱舞台”奖。2022年在爱奇艺《中国说唱巅峰对决》，早安所在“一席之地”联盟赢得冠军联盟。节目里中创作演出一首《麒麟》，成为年度爆款热歌，获得QQ音乐融合嘻哈颁奖礼 “最受欢迎个人单曲”、“年度突破艺人”。",
      "biographyDate": "2026-11-05"
    },
